import type { ReactNode } from 'react';
import { RotateCcw } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';

export interface FilterOption {
  value: string;
  label: string;
}

/** 「全部」哨兵值：空字符串 value 会被 Select 当作未选中渲染 placeholder，用它映射「筛选为空」 */
const ALL_VALUE = '__all__';

interface FilterSelectProps {
  value: string;
  onChange: (value: string) => void;
  options: readonly FilterOption[];
  placeholder: string;
  ariaLabel: string;
  allLabel?: string;
  className?: string;
}

/** 筛选下拉：带「全部」项用于清空（空值经哨兵映射回 ''） */
export function FilterSelect({
  value,
  onChange,
  options,
  placeholder,
  ariaLabel,
  allLabel = '全部',
  className,
}: FilterSelectProps) {
  return (
    <Select
      value={value === '' ? ALL_VALUE : value}
      // Base UI 的 onValueChange 会在清空时回调 null；Sentinel 负责把「全部」映射回空串
      onValueChange={(next) => onChange(next == null || next === ALL_VALUE ? '' : next)}
      items={[{ value: ALL_VALUE, label: allLabel }, ...options]}
    >
      <SelectTrigger className={className} aria-label={ariaLabel}>
        <SelectValue placeholder={placeholder} />
      </SelectTrigger>
      <SelectContent>
        <SelectItem value={ALL_VALUE}>{allLabel}</SelectItem>
        {options.map((option) => (
          <SelectItem key={option.value} value={option.value}>
            {option.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

interface FilterBarProps {
  /** 筛选控件组（搜索框、下拉等），从左到右排列 */
  children: ReactNode;
  /** 右侧动作区（刷新、视图切换等），自动推到行尾 */
  actions?: ReactNode;
  /** 提供时渲染「重置」按钮；筛选生效期间才传回调，可随筛选清空而消失 */
  onReset?: () => void;
}

/** 列表筛选工具条（S-02 工具条）：控件左排、动作右排、可选重置；窄屏按控件自然折行 */
export function FilterBar({ children, actions, onReset }: FilterBarProps) {
  return (
    <div className="mb-4 flex flex-wrap items-center gap-2">
      {children}
      {onReset ? (
        <Button variant="ghost" size="sm" onClick={onReset}>
          <RotateCcw aria-hidden />
          重置
        </Button>
      ) : null}
      {actions ? <div className="ml-auto flex items-center gap-2">{actions}</div> : null}
    </div>
  );
}
